const { query, messageCount, timestamp } = $input.first().json;
console.log(`[car-search] query="${query}" messageCount=${messageCount} at ${timestamp}`);
return $input.all();

const payload = $('Webhook').first().json.body;
const listings = $input.all();

const {
  budgetMin,
  budgetMax,
  bodyTypes = [],
  fuelTypes = [],
  transmission = 'any',
  minSeats,
  features = []
} = payload;

const mandatoryFeatures = features
  .filter(f => f.mandatory === true)
  .map(f => f.name.toLowerCase());

const matches = listings.filter(item => {
  const car = item.json;

  if (budgetMin !== null && budgetMin !== undefined) {
    if (car.price < budgetMin) return false;
  }

  if (budgetMax !== null && budgetMax !== undefined) {
    if (car.price > budgetMax) return false;
  }

  const normalizedBodyTypes = bodyTypes.map(b => b.toLowerCase());
  if (!normalizedBodyTypes.includes('any')) {
    if (!normalizedBodyTypes.includes(car.bodyType)) return false;
  }

  const normalizedFuelTypes = fuelTypes.map(f => f.toLowerCase());
  if (!normalizedFuelTypes.includes('any')) {
    if (!normalizedFuelTypes.includes(car.fuelType)) return false;
  }

  if (transmission.toLowerCase() !== 'any') {
    if (car.transmission !== transmission.toLowerCase()) return false;
  }

  if (minSeats !== null && minSeats !== undefined) {
    if (car.seatCount < minSeats) return false;
  }

  if (mandatoryFeatures.length > 0) {
    const carFeatures = JSON.parse(car.features || '[]').map(f => f.toLowerCase());
    for (const req of mandatoryFeatures) {
      if (!carFeatures.includes(req)) return false;
    }
  }

  return true;
});

const outputListings = matches.map(item => {
  const car = { ...item.json };
  car.features = JSON.parse(car.features || '[]');
  return car;
});

return [{ json: { listings: outputListings } }];

const input = $input.first().json;
const listings = input.listings || [];

const mappedResults = listings.map(car => ({
  make: car.make || '',
  model: car.model || '',
  bodyType: car.bodyType || null,
  year: car.year,
  price: (car.price !== undefined && car.price !== null) ? car.price : null,
  sourceUrl: car.source || null,
  fuelType: car.fuelType || null,
  mileage: car.mileage || null,
  transmission: car.transmission || null,
  seatCount: car.seatCount || null,
  features: car.features || []
}));

return [{ json: { ...input, mappedResults, totalCount: mappedResults.length } }];

const logResults = $('Log Results').first().json;
const listings = logResults.listings || [];
const matchCount = logResults.matchCount || 0;
const searchCriteria = logResults.searchCriteria || {};
const to = $('Webhook').first().json.body.userEmail;

function formatNum(n) {
  if (n == null) return null;
  return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function titleCase(s) {
  if (s == null || s === '') return null;
  return String(s).charAt(0).toUpperCase() + String(s).slice(1).toLowerCase();
}

function specRow(label, val) {
  const display = (val != null && val !== '') ? val : '<span style="color:#9ca3af;font-style:italic;">Not specified</span>';
  return `<tr><td style="color:#6b7280;font-size:13px;padding:3px 0;">${label}</td><td style="color:#111827;font-size:13px;padding:3px 0;">${display}</td></tr>`;
}

function buildCard(car) {
  const features = Array.isArray(car.features) ? car.features : [];
  const featuresHtml = features.length > 0
    ? features.join(' &bull; ')
    : '<span style="color:#9ca3af;font-style:italic;">No additional features listed</span>';
  const price = formatNum(car.price);
  const mileage = car.mileage != null ? formatNum(car.mileage) + ' km' : null;
  const linkHtml = car.source
    ? `<p style="margin:10px 0 0;"><a href="${car.source}" style="color:#2563eb;font-size:13px;text-decoration:none;">View listing &rarr;</a></p>`
    : '';
  return [
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:16px;border:1px solid #e5e7eb;border-radius:6px;">',
    '<tr>',
    '<td width="4" style="background-color:#2563eb;border-radius:6px 0 0 6px;"></td>',
    '<td style="padding:16px;background-color:#ffffff;">',
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>',
    `<td style="font-size:17px;font-weight:bold;color:#111827;">${car.year || ''} ${car.make || ''} ${car.model || ''}</td>`,
    `<td align="right" style="font-size:17px;font-weight:bold;color:#2563eb;">${price ? '€' + price : ''}</td>`,
    '</tr></table>',
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:10px;border-top:1px solid #e5e7eb;padding-top:10px;">',
    specRow('Fuel', titleCase(car.fuelType)),
    specRow('Mileage', mileage),
    specRow('Body', titleCase(car.bodyType)),
    specRow('Transmission', titleCase(car.transmission)),
    specRow('Seats', car.seatCount != null ? String(car.seatCount) : null),
    specRow('Condition', titleCase(car.condition)),
    specRow('Colour', titleCase(car.colour)),
    '</table>',
    `<p style="margin:8px 0 0;font-size:13px;color:#6b7280;">Features: <span style="color:#111827;">${featuresHtml}</span></p>`,
    linkHtml,
    '</td></tr></table>'
  ].join('');
}

function buildCriteria(c) {
  const rows = [];
  if (c.budgetMax != null) rows.push('Budget: up to €' + formatNum(c.budgetMax));
  const bt = (c.bodyTypes || []).filter(v => v !== 'any');
  if (bt.length) rows.push('Body types: ' + bt.join(', '));
  const ft = (c.fuelTypes || []).filter(v => v !== 'any');
  if (ft.length) rows.push('Fuel types: ' + ft.join(', '));
  if (c.transmission && c.transmission !== 'any') rows.push('Transmission: ' + titleCase(c.transmission));
  if (c.minSeats != null) rows.push('Minimum seats: ' + c.minSeats);
  const mf = (c.features || []).filter(f => f.mandatory === true);
  if (mf.length) rows.push('Required features: ' + mf.map(f => f.name).join(', '));
  if (!rows.length) return '<p style="margin:0;color:#9ca3af;font-style:italic;font-size:14px;">No specific criteria applied</p>';
  return rows.map(r => `<p style="margin:2px 0;color:#374151;font-size:14px;">${r}</p>`).join('');
}

const subject = `Your car matches: ${matchCount} result(s) found`;
const carCards = listings.map(buildCard).join('');
const criteria = buildCriteria(searchCriteria);

const htmlBody = `<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">
<html xmlns="http://www.w3.org/1999/xhtml" lang="en">
<head>
<meta http-equiv="Content-Type" content="text/html; charset=UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<meta name="x-apple-disable-message-reformatting" />
<title>Your Car Recommendations</title>
</head>
<body style="margin:0;padding:0;background-color:#f3f4f6;font-family:Arial,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f3f4f6;padding:24px 16px;">
<tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;">
<tr><td style="background-color:#2563eb;padding:24px 32px;border-radius:8px 8px 0 0;">
<h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:bold;">Your Car Recommendations</h1>
<p style="margin:6px 0 0;color:#bfdbfe;font-size:15px;">${matchCount} vehicle(s) matched your criteria</p>
</td></tr>
<tr><td style="background-color:#f9fafb;padding:16px 32px;border-bottom:1px solid #e5e7eb;">
<p style="margin:0 0 8px;color:#374151;font-size:12px;font-weight:bold;text-transform:uppercase;letter-spacing:0.05em;">Search Criteria</p>
${criteria}
</td></tr>
<tr><td style="background-color:#ffffff;padding:24px 32px;">
${carCards}
</td></tr>
<tr><td style="background-color:#f9fafb;padding:14px 32px;border-top:1px solid #e5e7eb;border-radius:0 0 8px 8px;text-align:center;">
<p style="margin:0;color:#9ca3af;font-size:12px;">Results generated by Car Buying Assistant</p>
</td></tr>
</table>
</td></tr>
</table>
</body>
</html>`;

return [{ json: { subject, htmlBody, to } }];
